    /// Marks every episode in `episodes` as watched, then reschedules pending episode notifications.
    ///
    /// Delegates per-episode insertion to `markEpisodeWatched` (idempotent). After all records are
    /// inserted, saves the context and rebuilds the notification queue so that any pending
    /// notifications for watched episodes are cancelled or updated.
    ///
    /// - Parameters:
    ///   - mediaId: The TMDB ID of the show the season belongs to.
    ///   - seasonNumber: The season whose episodes are being marked watched.
    ///   - episodes: The full episode list for the season.
    ///   - context: SwiftData context used for both reads and inserts.
    func markAllEpisodesOfSeasonWatched(
        mediaId: Int,
        seasonNumber: Int,
        episodes: [Episode],
        context: ModelContext
    ) async {
        for episode in episodes {
            markEpisodeWatched(
                mediaId: mediaId,
                episodeId: episode.id,
                seasonNumber: episode.seasonNumber,
                episodeNumber: episode.episodeNumber,
                context: context
            )
        }

        try? context.save()

        let items = fetchAllWatchlistItems(context: context)
        await NotificationManager.shared.rescheduleEpisodeNotifications(items: items)
    }

}

